// quietWindow is the negative-assertion window: after a Notify that must derive
// nothing, the pool is given this long to (wrongly) schedule and run a Match
// before the test accepts the absence.
const quietWindow = 250 * time.Millisecond

// assertNoMatch polls the given sources' Match counters for the whole quiet
// window, failing on the first call. Negative derivations have no completion
// signal — only a bounded window in which a leak would have to show up.
func assertNoMatch(t *testing.T, srcs ...*succeedSrc) {
	t.Helper()
	deadline := time.Now().Add(quietWindow)
	for time.Now().Before(deadline) {
		for _, src := range srcs {
			if calls := atomic.LoadInt32(&src.calls); calls != 0 {
				t.Fatalf("%s ran %d Match calls, want 0 (derivation leaked past its gate)", src.id, calls)
			}
		}
		time.Sleep(5 * time.Millisecond)
	}
}

// waitIdle polls the queue stats until nothing is pending or in flight (the
// derivation sweep has fed and the pool has drained) or the deadline elapses.
func waitIdle(t *testing.T, q *Queue, timeout time.Duration) {
	t.Helper()
	deadline := time.Now().Add(timeout)
	for time.Now().Before(deadline) {
		st := q.Stats()
		if st.Pending == 0 && st.InFlight == 0 {
			return
		}
		time.Sleep(time.Millisecond)
	}
	t.Fatalf("queue not idle after %v: %+v", timeout, q.Stats())
}

// TestGateDerivation pins spec scenario de17e2ba196a1bbf (plugin-title-enrichment
// box 2.3): enabling a gate wakes derivation through the EXISTING Queue.Notify —
// no rescan and no new lifecycle transitions; rows already carrying the source's
// namespace derive nothing on the wake. Provenance is structural: in this
// harness deps.Plugins is nil and the sync Enrich/scan seam (scan.runScan ->
// enrich.Enrich) is never invoked, so every Match call is attributable to the
// queue's Notify -> derive -> drain path alone.
func TestGateDerivation(t *testing.T) {
	ctx := context.Background()

	// The enable story end-to-end: a row enriched WITHOUT tmdb's namespace
	// while tmdb sits gated derives nothing; writing the enable pref and
	// calling the pre-existing Notify wakes derivation, and the drain derives
	// tmdb from the RETAINED document (the parsed leg is still in the doc) —
	// the row reaches ready with the namespace landed. No rescan ran (nothing
	// in the harness could rescan) and no lifecycle transition beyond the
	// ordinary drain/settle advancement was introduced.
	t.Run("enable_pref_wakes_derivation", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, err := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		if err != nil {
			t.Fatalf("CreateLibrary: %v", err)
		}
		doc := baseDoc("Show/S01E01.mkv")
		doc["sources"] = map[string]any{"tv-parser": map[string]any{"title": "parsed"}}
		putItem(t, s, "i_wake", libID, statusEnriched, doc)
		parser := &succeedSrc{id: "tv-parser"}
		tmdb := &succeedSrc{id: "tmdb"}
		if err := s.UpsertMetadataSourcePref(ctx, store.MetadataSourcePref{
			ModuleID: "tv", PluginID: "tmdb", Enabled: false,
		}); err != nil {
			t.Fatalf("UpsertMetadataSourcePref: %v", err)
		}
		q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{Backoff: time.Millisecond})
		q.resolve = mapResolver{"tv-parser": parser, "tmdb": tmdb}.resolver()

		// Gated, the row derives nothing — the pending set is empty both on a
		// direct derivation and on the Start sweep, and the row sits untouched.
		tasks, err := q.deriveLibrary(ctx, libID)
		if err != nil {
			t.Fatalf("deriveLibrary: %v", err)
		}
		if got := pluginIDs(tasks); got["tmdb"] {
			t.Fatalf("gated tmdb derived before the enable: %v", got)
		}
		if err := q.Start(ctx); err != nil {
			t.Fatalf("Start: %v", err)
		}
		defer q.Stop()
		q.Notify(ctx, libID)
		waitIdle(t, q, 2*time.Second)
		if calls := atomic.LoadInt32(&tmdb.calls); calls != 0 {
			t.Fatalf("gated tmdb drained %d Match calls before the enable, want 0", calls)
		}
		if it, err := s.GetItem(ctx, "i_wake"); err != nil || it.Status != statusEnriched {
			t.Fatalf("gated row disturbed pre-enable: status=%v err=%v", it.Status, err)
		}

		// The enable: the gate pref flips on, and the EXISTING Notify — not a
		// rescan, not a new transition — delivers the wake.
		if err := s.UpsertMetadataSourcePref(ctx, store.MetadataSourcePref{
			ModuleID: "tv", PluginID: "tmdb", Enabled: true,
		}); err != nil {
			t.Fatalf("UpsertMetadataSourcePref (enable): %v", err)
		}
		q.Notify(ctx, libID)
		_ = waitForStatus(t, s, "i_wake", statusReady, 2*time.Second)

		if calls := atomic.LoadInt32(&tmdb.calls); calls != 1 {
			t.Fatalf("tmdb Match calls = %d, want 1 (exactly the enable wake)", calls)
		}
		if calls := atomic.LoadInt32(&parser.calls); calls != 0 {
			t.Fatalf("tv-parser Match calls = %d, want 0 (namespace already carried)", calls)
		}
		it, err := s.GetItem(ctx, "i_wake")
		if err != nil {
			t.Fatalf("GetItem: %v", err)
		}
		if doc := decodeDoc(it.Document); !hasNamespace(doc, "tmdb") {
			t.Fatalf("tmdb namespace did not land after the enable wake: %v", doc["sources"])
		}
	})

	// A row already carrying the source's namespace derives NOTHING on the
	// enable wake — the hasNamespace skip holds after the gate opens, and the
	// row is never dispatched (no task, no Match, status untouched).
	t.Run("carried_namespace_derives_nothing_on_wake", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, err := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		if err != nil {
			t.Fatalf("CreateLibrary: %v", err)
		}
		doc := baseDoc("Show/S01E02.mkv")
		doc["sources"] = map[string]any{
			"tv-parser":     map[string]any{"title": "parsed"},
			"tmdb":          map[string]any{"title": "enriched"},
			"frame-grabber": map[string]any{"grabbed": true},
		}
		putItem(t, s, "i_done", libID, statusEnriched, doc)
		parser := &succeedSrc{id: "tv-parser"}
		tmdb := &succeedSrc{id: "tmdb"}
		if err := s.UpsertMetadataSourcePref(ctx, store.MetadataSourcePref{
			ModuleID: "tv", PluginID: "tmdb", Enabled: true,
		}); err != nil {
			t.Fatalf("UpsertMetadataSourcePref: %v", err)
		}
		q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{})
		q.resolve = mapResolver{"tv-parser": parser, "tmdb": tmdb}.resolver()

		tasks, err := q.deriveLibrary(ctx, libID)
		if err != nil {
			t.Fatalf("deriveLibrary: %v", err)
		}
		for _, tk := range tasks {
			if tk.rowID == "i_done" {
				t.Fatalf("carried namespace derived work on the enable: %+v", tk)
			}
		}
		if err := q.Start(ctx); err != nil {
			t.Fatalf("Start: %v", err)
		}
		defer q.Stop()
		q.Notify(ctx, libID)
		assertNoMatch(t, tmdb, parser)
		if it, err := s.GetItem(ctx, "i_done"); err != nil || it.Status != statusEnriched {
			t.Fatalf("fully-enriched row disturbed by the wake: status=%v err=%v", it.Status, err)
		}
	})

	// The wake derives ONLY the enabled source: sources still gated after the
	// flip stay out of the pending set, run no Match, and write no namespace.
	t.Run("wake_respects_other_sources_gates", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, err := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		if err != nil {
			t.Fatalf("CreateLibrary: %v", err)
		}
		putItem(t, s, "i_multi", libID, statusPending, baseDoc("Show/S01E03.mkv"))
		parser := &succeedSrc{id: "tv-parser"}
		tmdb := &succeedSrc{id: "tmdb"}
		for _, pref := range []store.MetadataSourcePref{
			{ModuleID: "tv", PluginID: "tmdb", Enabled: true}, // the enable
			{ModuleID: "tv", PluginID: "tv-parser", Enabled: false},
			{ModuleID: "tv", PluginID: "frame-grabber", Enabled: false},
		} {
			if err := s.UpsertMetadataSourcePref(ctx, pref); err != nil {
				t.Fatalf("UpsertMetadataSourcePref %s: %v", pref.PluginID, err)
			}
		}
		q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{Backoff: time.Millisecond})
		q.resolve = mapResolver{"tv-parser": parser, "tmdb": tmdb}.resolver()

		if err := q.Start(ctx); err != nil {
			t.Fatalf("Start: %v", err)
		}
		defer q.Stop()
		q.Notify(ctx, libID)
		_ = waitForStatus(t, s, "i_multi", statusReady, 2*time.Second)

		if calls := atomic.LoadInt32(&tmdb.calls); calls != 1 {
			t.Fatalf("tmdb Match calls = %d, want 1 (the enabled source wakes)", calls)
		}
		if calls := atomic.LoadInt32(&parser.calls); calls != 0 {
			t.Fatalf("gated tv-parser ran %d Match calls on the wake, want 0", calls)
		}
		it, err := s.GetItem(ctx, "i_multi")
		if err != nil {
			t.Fatalf("GetItem: %v", err)
		}
		doc := decodeDoc(it.Document)
		if !hasNamespace(doc, "tmdb") {
			t.Fatalf("enabled tmdb lost its namespace: %v", doc["sources"])
		}
		if hasNamespace(doc, "tv-parser") || hasNamespace(doc, "frame-grabber") {
			t.Fatalf("gated source wrote a namespace on the wake: %v", doc["sources"])
		}
	})

	// Best-effort companion to the enable story (NOT the spec probe — the
	// disable-absence direction is the spec's UNPROBEABLE scenario, accepted at
	// GATE 2 inspection): once a gated source's row has settled, the source
	// stays dormant — a further Notify derives nothing for it and it never
	// runs while its gate holds.
	t.Run("gated_source_stays_dormant_after_settle", func(t *testing.T) {
		s, reg := queueTestStore(t)
		libID, err := s.CreateLibrary(ctx, "tv", filepath.Join(t.TempDir(), "lib"), "TV")
		if err != nil {
			t.Fatalf("CreateLibrary: %v", err)
		}
		putItem(t, s, "i_dormant", libID, statusPending, baseDoc("Show/S01E04.mkv"))
		parser := &succeedSrc{id: "tv-parser"}
		tmdb := &succeedSrc{id: "tmdb"}
		if err := s.UpsertMetadataSourcePref(ctx, store.MetadataSourcePref{
			ModuleID: "tv", PluginID: "tv-parser", Enabled: false,
		}); err != nil {
			t.Fatalf("UpsertMetadataSourcePref: %v", err)
		}
		q := NewQueue(Deps{Store: s, Modules: reg}, QueueConfig{Backoff: time.Millisecond})
		q.resolve = mapResolver{"tv-parser": parser, "tmdb": tmdb}.resolver()

		if err := q.Start(ctx); err != nil {
			t.Fatalf("Start: %v", err)
		}
		defer q.Stop()
		q.Notify(ctx, libID)
		_ = waitForStatus(t, s, "i_dormant", statusReady, 2*time.Second)
		if calls := atomic.LoadInt32(&parser.calls); calls != 0 {
			t.Fatalf("gated tv-parser ran %d Match calls, want 0", calls)
		}
		// Post-settle sweeps keep the gated source dormant.
		q.Notify(ctx, libID)
		assertNoMatch(t, parser)
		tasks, err := q.deriveLibrary(ctx, libID)
		if err != nil {
			t.Fatalf("deriveLibrary: %v", err)
		}
		if got := pluginIDs(tasks); got["tv-parser"] {
			t.Fatalf("gated tv-parser re-derived after settle: %v", got)
		}
	})
}
